import type { Component, JSX } from "solid-js"
import { Match, Switch } from "solid-js"

// Sandbox driver brand marks.
//
// These are inlined rather than pulled from `@opencode-ai/ui/provider-icon`:
// that sprite is GENERATED by the icon-spritesheet generator and covers model
// providers, so hand-adding sandbox drivers there would be overwritten on the
// next regen. It also has no mark for daytona/modal/box/exe.
//
// Sources: Vercel, Cloudflare, Docker, Box and Modal marks are from
// simple-icons (CC0-1.0, https://github.com/simple-icons/simple-icons). The
// Daytona mark is the logomark from https://www.daytona.io/brand, normalised to
// its own bounding box. Every mark is monochrome and inherits `currentColor`,
// so the tiles stay legible in both themes and never fight the surface tokens.
// Brand marks remain trademarks of their owners and are used here only to
// identify each service in the picker.
//
// exe.dev publishes no mark, so it falls back to a monogram — see `Monogram`.

type LogoProps = { class?: string }

function svg(props: LogoProps & { viewBox: string; children: JSX.Element }) {
  return (
    <svg
      viewBox={props.viewBox}
      fill="currentColor"
      aria-hidden="true"
      class={props.class}
    >
      {props.children}
    </svg>
  )
}

