// The published asset is a 454x320 brand tile; this viewBox crops to the
// logomark's own bounding box so it optically matches the 24x24 marks above.
const Daytona: Component<LogoProps> = (props) =>
  svg({
    ...props,
    viewBox: "94 130 50.93 53.07",
    children: (
      <>
        <path d="m126.103 130-15.679 15.678v-6.703h-6.335v15.31h6.335v-8.607l4.48 4.48 15.678-15.679zm-4.592 13.726h21.117v6.335h-21.117zM96.7 165.899h9.244L94 153.955l4.48-4.48 12.041 12.041-4.383 4.383h9.04v6.335H96.701zm16.967 17.172 12.597-12.597v9.679h6.335v-19.006h-6.335v9.136l-4.384-4.384-12.692 12.692z" />
        <path d="m126.263 154.541 14.185 14.185 4.48-4.479-14.185-14.186z" />
      </>
    ),
  })

/** Fallback for drivers with no published mark (currently exe.dev). */
const Monogram: Component<LogoProps & { label: string }> = (props) => (
  <span
    aria-hidden="true"
    class={`grid place-items-center rounded-[5px] border border-border-base text-11-medium ${props.class ?? ""}`}
  >
    {props.label.slice(0, 1).toUpperCase()}
  </span>
)

export const SandboxDriverLogo: Component<{ id: string; label: string; class?: string }> = (props) => (
  <Switch fallback={<Monogram label={props.label} class={props.class} />}>
    <Match when={props.id === "vercel"}>
      <Vercel class={props.class} />
    </Match>
    <Match when={props.id === "cloudflare"}>
      <Cloudflare class={props.class} />
    </Match>
    <Match when={props.id === "docker"}>
      <Docker class={props.class} />
    </Match>
    <Match when={props.id === "box"}>
      <Box class={props.class} />
    </Match>
    <Match when={props.id === "modal"}>
      <Modal class={props.class} />
    </Match>
    <Match when={props.id === "daytona"}>
      <Daytona class={props.class} />
    </Match>
  </Switch>
)
